CREATE TABLE `battery_info` (
  `battery_id` int NOT NULL COMMENT '电池组编号 (1-124)',
  `battery_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '电池组名称',
  `manufacturer` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'Severson Lab' COMMENT '制造商',
  `model` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'LFP/Graphite' COMMENT '型号',
  `rated_capacity` decimal(10,4) DEFAULT '1.1000' COMMENT '额定容量(Ah)',
  `rated_voltage` decimal(10,4) DEFAULT '3.3000' COMMENT '额定电压(V)',
  `manufacture_date` date DEFAULT NULL COMMENT '生产日期',
  `first_use_date` date DEFAULT NULL COMMENT '首次使用日期',
  `status` enum('active','retired','testing') COLLATE utf8mb4_unicode_ci DEFAULT 'active' COMMENT '状态',
  `dataset_type` enum('train','validation','test') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '数据集类型',
  `total_cycles` int DEFAULT '0' COMMENT '总循环次数',
  `notes` text COLLATE utf8mb4_unicode_ci COMMENT '备注信息',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`battery_id`),
  KEY `idx_status` (`status`),
  KEY `idx_dataset_type` (`dataset_type`),
  KEY `idx_battery_name` (`battery_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='电池基本信息表';
